mapper.select:
SELECT id, event_id, event_type, CAST(payload AS CHAR) AS payload,
       trace_id, retry_count, occurred_at, version
FROM event_outbox
WHERE context_name = #{contextName}
  AND event_type = #{eventType}
  AND (
      status = 'NEW'
      OR (status IN ('FAILED', 'PROCESSING')
          AND next_retry_at <= #{readyAt})
  )
ORDER BY id
LIMIT #{limit}
